function store_h($v) { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function store_time($timestamp) {
    if ((int)$timestamp < 1) return '–';
    $zone = defined('DEFAULT_TIMEZONE') && preg_match('/^[A-Za-z_]+(?:\/[A-Za-z0-9_+\-]+)+$/', (string)DEFAULT_TIMEZONE)
        ? (string)DEFAULT_TIMEZONE : 'Europe/Berlin';
    try {$tz = new DateTimeZone($zone);} catch (Throwable $ignored) {$tz = new DateTimeZone('Europe/Berlin');}
    $date = new DateTime('@'.(int)$timestamp);
    $date->setTimezone($tz);
    return $date->format('d.m.Y H:i');
}
function store_installed($db, $type, $slug) {
