}
function store_active($db, $slug) {
    $r=$db->query("SELECT `active` FROM `{TP}addons` WHERE `directory`='".$db->escapeString($slug)."' AND `type`='module' LIMIT 1");
    return $r && ($x=$r->fetchRow(MYSQLI_ASSOC)) ? (int)$x['active']===1 : false;
}
function store_origin($db, $type, $slug) {
    $r=$db->query("SELECT * FROM `{TP}mod_store_origins` WHERE `package_type`='".$db->escapeString($type)."' AND `package_slug`='".$db->escapeString($slug)."' LIMIT 1");
    return $r ? $r->fetchRow(MYSQLI_ASSOC) : null;
}
function store_remember_origin($db, $package, $source) {
    $db->query("INSERT INTO `{TP}mod_store_origins` (`package_type`,`package_slug`,`source_id`,`source_name`,`catalog_url`,`package_version`,`updated_at`) VALUES ('".
        $db->escapeString($package['type'])."','".$db->escapeString($package['slug'])."',".(int)$source['id'].",'".$db->escapeString($source['name'])."','".
        $db->escapeString($source['catalog_url'])."','".$db->escapeString($package['version'])."',".time().") ON DUPLICATE KEY UPDATE `source_id`=VALUES(`source_id`),`source_name`=VALUES(`source_name`),`catalog_url`=VALUES(`catalog_url`),`package_version`=VALUES(`package_version`),`updated_at`=VALUES(`updated_at`)");
}
function store_valid($p, $catalog) {
    foreach (array('slug','type','name','version','platform','sha256','download_url','size') as $f) if (!isset($p[$f])) throw new RuntimeException(wbce_store_text('catalog_incomplete'));
    if (!in_array($p['type'],array('module','template','admin_template','language','cms'),true) || !preg_match('/^[a-z][a-z0-9_-]{1,189}$/i',$p['slug']) || !preg_match('/^[a-f0-9]{64}$/i',$p['sha256'])) throw new RuntimeException(wbce_store_text('package_invalid'));
    if ((int)$p['size']<1 || (int)$p['size']>536870912 || parse_url($catalog,PHP_URL_HOST)!==parse_url($p['download_url'],PHP_URL_HOST) || parse_url($p['download_url'],PHP_URL_SCHEME)!=='https') throw new RuntimeException(wbce_store_text('package_url_unsafe'));
    if (!empty($p['preview_url']) && (parse_url($p['preview_url'],PHP_URL_SCHEME)!=='https'
        || strcasecmp((string)parse_url($catalog,PHP_URL_HOST),(string)parse_url($p['preview_url'],PHP_URL_HOST))!==0
        || parse_url($p['preview_url'],PHP_URL_USER)!==null || parse_url($p['preview_url'],PHP_URL_PASS)!==null)) throw new RuntimeException(wbce_store_text('preview_url_unsafe'));
    return $p['type'].'|'.$p['slug'].'|'.$p['version'];
}
function store_required_wbce($package) {
    $platform=trim(isset($package['platform'])?(string)$package['platform']:'');
    return preg_match('/\d+(?:\.\d+){1,2}/',$platform,$match)?$match[0]:'';
}
function store_cms_compatible($package) {
    global $database;
    return WbceStoreUpdateChecker::installable($database, $package);
}
function store_assert_cms_compatible($package) {
    if(store_cms_compatible($package))return;
    if(!empty($package['requires_any']))throw new RuntimeException('Dieses Paket benötigt '.str_replace('|',' oder ',$package['requires_any']).'.');
    throw new RuntimeException('Dieses Paket benötigt mindestens WBCE '.store_required_wbce($package).'. Installiert ist WBCE '.(defined('WBCE_VERSION')?WBCE_VERSION:'unbekannt').'.');
}
function store_incompatibility_reason($package) {
    global $database;
    $required=store_required_wbce($package);
    if(!wbce_store_cms_version_meets($required))return 'Dieses Paket benötigt mindestens WBCE '.$required.'. Installiert ist '.(defined('WBCE_VERSION')?WBCE_VERSION:'eine unbekannte Version').'.';
    $requirements=trim(isset($package['requires_any'])?(string)$package['requires_any']:'');
    if($requirements!==''&&!wbce_store_any_requirement_meets($requirements,$database))return 'Dieses Paket benötigt '.str_replace('|',' oder ',$requirements).'.';
    foreach(store_dependencies($package) as $slug=>$minimum){$installed=store_installed($database,'module',$slug);if($installed!==''&&version_compare($installed,$minimum,'>='))continue;global $http;if(!store_dependency_offer($database,$http,$slug,$minimum))return 'Die benötigte kompatible Abhängigkeit '.$slug.' ab Version '.$minimum.' ist in keinem aktiven Store verfügbar.';}
    return '';
}
function store_dependencies($package) {
    $result=array();$raw=trim(isset($package['dependencies'])?(string)$package['dependencies']:'');
    if($raw==='')return $result;
    foreach(preg_split('/\s*,\s*/',$raw,-1,PREG_SPLIT_NO_EMPTY) as $dependency){
        if(!preg_match('/^([a-z][a-z0-9_-]{1,189})(?:\s*>=\s*([0-9][0-9A-Za-z._-]*))?$/i',$dependency,$match))throw new RuntimeException(wbce_store_text('dependency_invalid',array('dependency'=>$dependency)));
        $result[$match[1]]=isset($match[2])?$match[2]:'0';
    }
    return $result;
}
function store_missing_dependencies($database,$package) {
    $missing=array();
    foreach(store_dependencies($package) as $slug=>$minimum){
        if($slug==='wbce_hook_bridge'&&wbce_store_native_hooks_available())continue;
        $installed=store_installed($database,'module',$slug);
        if($installed===''||version_compare($installed,$minimum,'<'))$missing[]=$slug.'>='.$minimum;
    }
    return implode(',',$missing);
}
function store_dependency_offer($database,$http,$slug,$minimum) {
    $best=null;$result=$database->query("SELECT * FROM `{TP}mod_store_sources` WHERE `active`=1 ORDER BY `name`");
    while($result&&($source=$result->fetchRow(MYSQLI_ASSOC))){
        try{$catalog=$http->json($source['catalog_url'],$source['access_token']);}catch(Throwable $ignored){continue;}
        if(empty($catalog['packages'])||!is_array($catalog['packages']))continue;
        foreach($catalog['packages'] as $available){
            try{store_valid($available,$source['catalog_url']);}catch(Throwable $ignored){continue;}
            if($available['type']!=='module'||$available['slug']!==$slug||!store_cms_compatible($available)||version_compare((string)$available['version'],$minimum,'<'))continue;
            if($best===null||version_compare($available['version'],$best['package']['version'],'>'))$best=array('source'=>$source,'catalog'=>$catalog,'package'=>$available);
        }
    }
    return $best;
}
function store_install_dependencies($database,$http,$package,$confirmed,&$stack=array()) {
    foreach(store_dependencies($package) as $slug=>$minimum){
        if($slug==='wbce_hook_bridge'&&wbce_store_native_hooks_available())continue;
        $installed=store_installed($database,'module',$slug);
        if($installed!==''&&version_compare($installed,$minimum,'>='))continue;
        if(!$confirmed)throw new RuntimeException('Das Paket benötigt '.$slug.' ab Version '.$minimum.'. Bitte die automatische Installation der Abhängigkeiten bestätigen.');
        if(isset($stack[$slug]))throw new RuntimeException('Zirkuläre Modulabhängigkeit erkannt: '.$slug);
        $stack[$slug]=true;$offer=store_dependency_offer($database,$http,$slug,$minimum);
        if(!$offer)throw new RuntimeException('Die benötigte kompatible Abhängigkeit '.$slug.' ab Version '.$minimum.' ist in keinem aktiven Store verfügbar.');
        $candidate=$offer['package'];$dependencySource=$offer['source'];
        store_install_dependencies($database,$http,$candidate,true,$stack);
        $temporary=$http->download($candidate['download_url'],(int)$candidate['size'],$dependencySource['access_token']);
        try{(new WbceRepositoryPackageInstaller($database))->install($temporary,$candidate,false);store_remember_origin($database,$candidate,$dependencySource);}finally{@unlink($temporary);}
        unset($stack[$slug]);
    }
}
function store_catalog_url($url) {
    $url=trim((string)$url);
    $path=rtrim((string)parse_url($url,PHP_URL_PATH),'/');$supported=wbce_store_ends_with($path,'/api')||wbce_store_ends_with($path,'/modules/api/store');
    if(parse_url($url,PHP_URL_SCHEME)!=='https'||!filter_var($url,FILTER_VALIDATE_URL)||!$supported)throw new RuntimeException(wbce_store_text('catalog_url_invalid'));
    return rtrim($url,'/').'/';
}
