function store_release_install_lock($database) {
    $lockName=$database->escapeString('wbce.store.autoupdate');
    for($attempt=0;$attempt<32;$attempt++){
        $result=$database->query("SELECT RELEASE_LOCK('$lockName') AS released");
        $row=$result?$result->fetchRow(MYSQLI_ASSOC):null;
        if(!$row||(int)$row['released']!==1)break;
    }
}
function store_release_stale_owned_install_lock($database) {
    $lockName=$database->escapeString('wbce.store.autoupdate');
    $result=$database->query("SELECT IS_USED_LOCK('$lockName') AS owner, CONNECTION_ID() AS current_id");
    $row=$result?$result->fetchRow(MYSQLI_ASSOC):null;
    if($row&&$row['owner']!==null&&(string)$row['owner']===(string)$row['current_id'])store_release_install_lock($database);
}

