$optionsPage=isset($_GET['view'])&&$_GET['view']==='options';$storeAutoUpdateTask=null;if(store_worker_table_exists($database)){$autoResult=$database->query("SELECT `active`,`cron_expression`,`last_run`,`last_status`,`last_message` FROM `{TP}mod_worker_tasks` WHERE `worker_id`='store.autoupdate' AND `managed`=1 ORDER BY `id` LIMIT 1");$storeAutoUpdateTask=$autoResult?$autoResult->fetchRow(MYSQLI_ASSOC):null;}$sources=array();$allSources=array();$r=$database->query('SELECT * FROM `{TP}mod_store_sources` ORDER BY `name`');while($r&&($x=$r->fetchRow(MYSQLI_ASSOC))){$allSources[]=$x;if((int)$x['active']===1)$sources[]=$x;}
$sourceStates=array();if($optionsPage){foreach($allSources as $stateSource){$state=array('test_store'=>null,'token_required'=>null,'token_configured'=>trim((string)$stateSource['access_token'])!=='','login_success'=>false,'error'=>'');try{$stateCatalog=$http->json($stateSource['catalog_url'],$stateSource['access_token']);$capabilities=isset($stateCatalog['capabilities'])&&is_array($stateCatalog['capabilities'])?$stateCatalog['capabilities']:array();$state['test_store']=!empty($capabilities['test_store'])||!empty($capabilities['is_test_store']);$state['token_required']=!empty($capabilities['token_required'])||!empty($capabilities['require_token']);$state['login_success']=true;}catch(Throwable $stateError){$state['error']=$stateError->getMessage();if(stripos($state['error'],'Token')!==false){$state['test_store']=true;$state['token_required']=true;}}$sourceStates[(int)$stateSource['id']]=$state;}}
$offers=array();$catalogErrors=array();$storeIsPost=$_SERVER['REQUEST_METHOD']==='POST';
if(!$optionsPage){foreach($sources as $source){try{$catalog=$storeIsPost?$http->cachedJson($source['catalog_url'],$source['access_token']):$http->json($source['catalog_url'],$source['access_token']);if(!is_array($catalog))continue;$testStore=isset($catalog['capabilities']['test_store'])&&$catalog['capabilities']['test_store']===true;$allowDowngrade=$testStore&&isset($catalog['capabilities']['allow_downgrade'])&&$catalog['capabilities']['allow_downgrade']===true;$byPackage=array();foreach($catalog['packages'] as $p){try{$p['_ref']=store_valid($p,$source['catalog_url']);}catch(Throwable $ignored){continue;}$byPackage[$p['type'].'|'.$p['slug']][]=$p;}foreach($byPackage as $key=>$versions){usort($versions,function($a,$b){return version_compare($b['version'],$a['version']);});$latest=$versions[0];$installedForOffer=store_installed($database,$latest['type'],$latest['slug']);$compatibleUpdate=false;if($installedForOffer!==''){if($testStore){foreach($versions as $version){if(store_cms_compatible($version)&&version_compare($version['version'],$installedForOffer,'>')){$compatibleUpdate=true;break;}}}else{$compatibleUpdate=store_cms_compatible($latest)&&version_compare($latest['version'],$installedForOffer,'>');}}$candidate=array('source'=>$source,'test_store'=>$testStore,'allow_downgrade'=>$allowDowngrade,'versions'=>$versions,'latest'=>$latest,'compatible_update'=>$compatibleUpdate);if(!isset($offers[$key])||($candidate['compatible_update']&&!$offers[$key]['compatible_update'])||($candidate['compatible_update']===$offers[$key]['compatible_update']&&version_compare($candidate['latest']['version'],$offers[$key]['latest']['version'],'>')))$offers[$key]=$candidate;}}catch(Throwable $exception){$catalogErrors[]=$source['name'].': '.$exception->getMessage();}}}
$storeUpdateReport=$optionsPage?array('compatible'=>array(),'incompatible'=>array()):WbceStoreUpdateChecker::report($database,$storeIsPost);
$storeAvailableUpdateCount=count($storeUpdateReport['compatible']);
$storeIncompatibleUpdateCount=count($storeUpdateReport['incompatible']);
ob_start();
