array();if($packageDowngrade&&$installed!=='')$downgrades=array_values(array_filter($compatibleVersions,function($p)use($installed){return version_compare($p['version'],$installed,'<');}));$dialogId='store-downgrade-'.(int)$source['id'].'-'.substr(md5($type.'|'.$slug),0,12);$uninstallDialogId='store-uninstall-'.(int)$source['id'].'-'.substr(md5($type.'|'.$slug),0,12);?>
<article class="store-package" data-store-name="<?php echo store_h(mb_strtolower($first['name'],'UTF-8'));?>" data-store-type="<?php echo store_h($label);?>" data-store-category="<?php echo store_h($category);?>" data-store-installed="<?php echo $installed!==''?'1':'0';?>" data-store-update="<?php echo $updateAvailable?'1':'0';?>" data-store-version="<?php echo store_h($first['version']);?>" data-store-package-created="<?php echo isset($first['package_created_at'])?(int)$first['package_created_at']:0;?>" data-store-update-created="<?php echo isset($first['created_at'])?(int)$first['created_at']:0;?>"><h5><?php echo store_h($first['name']);?></h5><div><?php if($installed!==''):?><span class="store-badge ok">Installiert: <?php echo store_h($installed);?></span><?php else:?><span class="store-badge">Nicht installiert</span><?php endif;?> <?php if($updateAvailable):?><span class="store-badge">Update verfügbar: <?php echo store_h($newer[0]['version']);?></span><?php elseif(!$newer&&$installed!==''):?><span class="store-badge ok">Aktuell</span><?php endif;?><?php if($latestNeedsNewerCms):?> <span class="store-badge incompatible"><?php echo !empty($first['requires_any'])?store_h(str_replace('|',' oder ',$first['requires_any'])):'Mindestens WBCE '.store_h(store_required_wbce($first)).' erforderlich';?></span><?php endif;?><?php if($supportsActivation&&$type==='module'&&$installed!==''&&$slug!=='store'):?> <span class="store-badge <?php echo store_active($database,$slug)?'ok':'';?>"><?php echo store_active($database,$slug)?'Aktiv':'Deaktiviert';?></span><?php endif;?></div><p class="store-description"><?php echo nl2br(store_h(isset($first['description'])&&trim($first['description'])!==''?$first['description']:'Für dieses Paket ist noch keine Beschreibung hinterlegt.'));?></p><p><small><?php if($origin):?><strong>Installiert aus:</strong> <a href="<?php echo store_h($origin['catalog_url']);?>" target="_blank" rel="noopener noreferrer"><?php echo store_h($origin['source_name']