<?php if($allNewer):$selectedRef=$newer?$newer[0]['_ref']:'';$blockedReason=$blockedVersions?store_incompatibility_reason($blockedVersions[0]):'';?><form method="post" class="store-version-action" style="display:inline"><?php echo $admin->getFTAN();?><input type="hidden" name="store_action" value="install"><input type="hidden" name="source_id" value="<?php echo (int)$source['id'];?>"><div class="store-action-requirement" <?php echo $blockedReason===''?'hidden':'';?>><?php echo store_h($blockedReason);?></div><select name="package_ref" aria-label="Version" <?php echo $blockedAction?'disabled':'';?>><?php foreach($allNewer as $p):$reason=store_incompatibility_reason($p);$compatible=$reason==='';?><option value="<?php echo store_h($p['_ref']);?>" data-compatible="<?php echo $compatible?'1':'0';?>" data-reason="<?php echo store_h($reason);?>" data-dependencies="<?php echo $compatible?store_h(store_missing_dependencies($database,$p)):'';?>" <?php echo !$compatible?'disabled class="store-version-incompatible"':'';?> <?php echo $compatible&&$p['_ref']===$selectedRef?'selected':'';?>>Version <?php echo store_h($p['version']);?><?php echo !$compatible?' – nicht kompatibel':'';?></option><?php endforeach;?></select> <button class="store-button" <?php echo $blockedAction?'disabled aria-disabled="true"':'';?>><?php echo $installed===''?'Installieren':'Update';?></button></form><?php endif;?>
