function renderAuthors(){var app=document.getElementById('store-app');if(!app)return;app.querySelectorAll('.store-package').forEach(function(card){if(card.querySelector('.store-package-author'))return;var key=(card.getAttribute('data-store-name')||'')+'|'+(card.getAttribute('data-store-type')||''),author=authors[key]||'';if(!author)return;var line=document.createElement('p'),description=card.querySelector('.store-description');line.className='store-package-author';line.innerHTML='<small><strong>'+authorLabel+':</strong> <span></span></small>';line.querySelector('span').textContent=author;if(description&&description.nextSibling)description.parentNode.insertBefore(line,description.nextSibling);else card.appendChild(line);});}
renderAuthors();var authorApp=document.getElementById('store-app');if(authorApp&&window.MutationObserver){var authorQueued=false;new MutationObserver(function(){if(authorQueued)return;authorQueued=true;window.requestAnimationFrame(function(){authorQueued=false;renderAuthors();});}).observe(authorApp,{childList:true,subtree:true});}
