<script>
(function(){
var dates=<?php $storeVersionDates=array();foreach($offers as $dateOffer){foreach($dateOffer['versions'] as $datePackage){$storeVersionDates[$datePackage['_ref']]=array('timestamp'=>isset($datePackage['created_at'])?(int)$datePackage['created_at']:0,'formatted'=>store_time(isset($datePackage['created_at'])?$datePackage['created_at']:0));}}echo json_encode($storeVersionDates,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>;
var publishedLabel=<?php echo json_encode(wbce_store_text('published'),JSON_UNESCAPED_UNICODE);?>,lastUpdateLabel=<?php echo json_encode(wbce_store_text('last_update'),JSON_UNESCAPED_UNICODE);?>;
function findByTimestamp(timestamp){var keys=Object.keys(dates);for(var i=0;i<keys.length;i++){if(Number(dates[keys[i]].timestamp)===Number(timestamp))return dates[keys[i]];}return null;}
function updateSelection(select,display){var option=select.options[select.selectedIndex],entry=option?dates[option.value]:null;display.textContent=publishedLabel+': '+(entry?entry.formatted:'–');}
function renderDates(){var app=document.getElementById('store-app');if(!app)return;app.querySelectorAll('.store-package').forEach(function(card){if(card.querySelector('.store-package-dates'))return;var first=findByTimestamp(card.getAttribute('data-store-package-created')),last=findByTimestamp(card.getAttribute('data-store-update-created')),line=document.createElement('p');line.className='store-package-dates';line.innerHTML='<small><span><strong>'+publishedLabel+':</strong> '+(first?first.formatted:'–')+'</span><span><strong>'+lastUpdateLabel+':</strong> '+(last?last.formatted:'–')+'</span></small>';var actions=card.querySelector('.store-actions');card.insertBefore(line,actions||null);});app.querySelectorAll('.store-version-action select[name="package_ref"],.store-dialog select[name="package_ref"]').forEach(function(select){var display=select.parentNode.querySelector('.store-selected-version-date');if(!display){display=document.createElement('div');display.className='store-selected-version-date';select.parentNode.insertBefore(display,select);select.addEventListener('change',function(){updateSelection(select,display);});}updateSelection(select,display);});}
window.wbceStoreRenderDates=renderDates;renderDates();var dateApp=document.getElementById('store-app');if(dateApp&&window.MutationObserver){var queued=false;new MutationObserver(function(){if(queued)return;queued=true;window.requestAnimationFrame(function(){queued=false;renderDates();});}).observe(dateApp,{childList:true,subtree:true});}
})();
</script>
