<script>
(function(){
if(window.wbceStoreSequentialUpdatesBound)return;
window.wbceStoreSequentialUpdatesBound=true;
// Each package gets its own asynchronous request so the interface can show
// completed/total progress. The released PHP session keeps WBCE responsive.
document.addEventListener('submit',function(event){
 var form=event.target.closest&&event.target.closest('.store-update-all');
 if(!form)return;
 event.preventDefault();event.stopImmediatePropagation();
 if(form.getAttribute('aria-busy')==='true')return;
 var section=form.closest('.store-updates'),tasks=[];
 if(section)section.querySelectorAll('.store-update-row form').forEach(function(rowForm){
  var action=rowForm.querySelector('input[name="store_action"]'),source=rowForm.querySelector('input[name="source_id"]'),ref=rowForm.querySelector('input[name="package_ref"]');
  if(action&&action.value==='install'&&source&&ref)tasks.push({source:source.value,ref:ref.value});
 });
 tasks.sort(function(a,b){var aStore=a.ref.indexOf('module|store|')===0,bStore=b.ref.indexOf('module|store|')===0;return aStore===bStore?0:(aStore?1:-1);});
 if(!tasks.length)return;
 form.setAttribute('aria-busy','true');
 var firstButton=form.querySelector('button');if(firstButton){firstButton.disabled=true;firstButton.classList.add('store-busy');}
 var index=0,errors=[];
 function findCurrentForm(task){
  var forms=document.querySelectorAll('.store-updates .store-update-row form');
  for(var i=0;i<forms.length;i++){
   var source=forms[i].querySelector('input[name="source_id"]'),ref=forms[i].querySelector('input[name="package_ref"]');
   if(source&&ref&&source.value===task.source&&ref.value===task.ref)return forms[i];
  }
  return null;
 }
 function updateProgress(){
  var button=document.querySelector('.store-update-all button');
  if(button){button.disabled=true;button.classList.add('store-busy');button.textContent=index+' von '+tasks.length+' installiert';}
  var app=document.querySelector('#store-app');if(app)app.querySelectorAll('button,select,input:not([type="hidden"]),textarea,a').forEach(function(control){if('disabled'in control)control.disabled=true;else control.setAttribute('aria-disabled','true');});
  document.querySelectorAll('.store-update-row form').forEach(function(singleForm){var single=singleForm.querySelector('button');if(single)single.hidden=true;var row=singleForm.closest('.store-update-row');if(row&&!row.querySelector('.store-update-install-state')){var state=document.createElement('span');state.className='store-update-install-state';state.textContent='Modul wird installiert …';row.appendChild(state);}});
 }
 function finishBulk(){var app=document.querySelector('#store-app');if(app)app.querySelectorAll('button,select,input:not([type="hidden"]),textarea,a').forEach(function(control){if('disabled'in control)control.disabled=false;else control.removeAttribute('aria-disabled');});document.querySelectorAll('.store-update-install-state').forEach(function(state){state.remove();});document.querySelectorAll('.store-update-row form button').forEach(function(single){single.hidden=false;});var button=document.querySelector('.store-update-all button');if(button){button.textContent=tasks.length+' von '+tasks.length+' installiert';button.classList.remove('store-busy');}}
 function next(){
  if(index>=tasks.length){
   finishBulk();
   if(errors.length)showNotice(errors.join(' | '),true);
   else showNotice('Alle kompatiblen Updates wurden installiert.',false);
   return;
  }
  updateProgress();
  var task=tasks[index],rowForm=findCurrentForm(task);
  if(!rowForm){index++;next();return;}
  var activeButton=rowForm.querySelector('button');if(activeButton){activeButton.hidden=true;activeButton.disabled=true;activeButton.classList.add('store-busy');}
