    if(!fresh||!current)throw new Error('Ungültige Serverantwort');
    if(error){var errorText=error.textContent.trim();if(errors.indexOf(errorText)===-1)errors.push(errorText);if(errorText.indexOf('Eine andere Store-Installation läuft bereits')!==-1)index=tasks.length;}
    current.innerHTML=fresh.innerHTML;
    if(window.wbceStoreBind)window.wbceStoreBind();
    if(window.wbceStoreRestoreState)window.wbceStoreRestoreState(saved);else if(window.wbceStoreApplyFilters)window.wbceStoreApplyFilters();
    index++;next();
   })
   .catch(function(error){var errorText=error&&error.message?error.message:'Ein Update ist fehlgeschlagen.';if(errors.indexOf(errorText)===-1)errors.push(errorText);if(errorText.indexOf('Eine andere Store-Installation läuft bereits')!==-1)index=tasks.length;else index++;next();});
 }
 function showNotice(message,isError){
  var area=document.querySelector('#store-app .store-toast-area');if(!area){window.alert(message);return;}
  var notice=document.createElement('div');notice.className='store-toast '+(isError?'store-error':'store-ok');notice.textContent=message;area.appendChild(notice);window.setTimeout(function(){if(notice.parentNode)notice.parentNode.removeChild(notice);},6000);
 }
 next();
},true);
})();
</script>
<script>
