function bindStoreFilterControls(){var app=document.querySelector('#store-app');if(!app)return;app.querySelectorAll('[data-store-search],[data-store-type],[data-store-category],[data-store-status],[data-store-sort]').forEach(function(control){if(control.getAttribute('data-store-filter-bound')==='1')return;control.setAttribute('data-store-filter-bound','1');control.addEventListener('input',storeApplyFilters);control.addEventListener('change',storeApplyFilters);});}
