 document.addEventListener('submit',function(event){var form=event.target,action=form&&form.querySelector&&form.querySelector('input[name="store_action"]');if(!action||action.value!=='install'||form.querySelector('input[name="install_dependencies"]'))return;var select=form.querySelector('select[name="package_ref"]'),reference=form.querySelector('input[name="package_ref"]'),option=select?select.options[select.selectedIndex]:reference,dependencies=option?option.getAttribute('data-dependencies')||'':'';if(!dependencies)return;event.preventDefault();event.stopImmediatePropagation();pendingForm=form;var isTwoFactor=/(^|,)two_factor>=/i.test(dependencies);dialog.querySelector('[data-dependency-title]').textContent=isTwoFactor?'2FA-Grundmodul installieren?':'Benötigte Module installieren?';dialog.querySelector('[data-dependency-message]').textContent=isTwoFactor?'Dieser 2FA-Provider benötigt das Grundmodul „2FA Authentifizierung“. Benötigt: '+dependencies:'Dieses Paket benötigt: '+dependencies;dialog.showModal();},true);
 dialog.querySelector('[data-dependency-cancel]').onclick=function(){pendingForm=null;dialog.close();};
 dialog.querySelector('[data-dependency-confirm]').onclick=function(){if(!pendingForm){dialog.close();return;}var confirmed=document.createElement('input');confirmed.type='hidden';confirmed.name='install_dependencies';confirmed.value='1';pendingForm.appendChild(confirmed);var form=pendingForm;pendingForm=null;dialog.close();if(typeof form.requestSubmit==='function')form.requestSubmit();else form.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));};
 dialog.addEventListener('click',function(event){if(event.target===dialog){pendingForm=null;dialog.close();}});
})();
